CREATE OR REPLACE FUNCTION public.tos_private_seven_scope(p_table text, p_row jsonb, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text:=public.tos_current_role();actor_client bigint;owner_client bigint;edt bigint;campaign bigint;support text;phase bigint;phase_edt bigint;phase_client bigint;
BEGIN
 IF auth.uid() IS NULL OR r IS NULL OR p_action IS NULL OR p_action NOT IN ('read','write') OR p_row IS NULL THEN RETURN false;END IF;
 SELECT u.client_id INTO actor_client FROM public.utilisateurs u WHERE u.auth_user_id=auth.uid() AND lower(coalesce(u.statut,''))='actif';
 IF actor_client IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients c WHERE c.id=actor_client) THEN RETURN false;END IF;
 IF r IN ('Client','Client-Admin') AND actor_client IS NULL THEN RETURN false;END IF;
 IF p_table IN ('relation_fields','relation_rules') THEN
  -- Shared rendering/Studio metadata have no tenant owner. Write is global-admin only.
  RETURN p_action='read' OR (r='Administrateur' AND actor_client IS NULL);
 END IF;
 IF p_action='write' AND r NOT IN ('Administrateur','Coordonnateur','Installateur') THEN RETURN false;END IF;
 owner_client:=nullif(p_row->>'client_id','')::bigint;
 support:=nullif(p_row->>'support_id','');
 IF p_table='edt_phases' THEN edt:=(p_row->>'edt_id')::bigint;IF edt IS NULL THEN RETURN false;END IF;
 ELSIF p_table='edt_supports' THEN edt:=(p_row->>'edt_id')::bigint;phase:=(p_row->>'phase_id')::bigint;IF edt IS NULL OR support IS NULL THEN RETURN false;END IF;
 ELSIF p_table='enjeux_terrain' THEN phase:=(p_row->>'edt_phase_id')::bigint;IF support IS NULL THEN RETURN false;END IF;IF r IN ('Client','Client-Admin') AND (p_row->>'client_visible')::boolean IS NOT TRUE THEN RETURN false;END IF;
 ELSIF p_table='inspections_terrain' THEN campaign:=(p_row->>'campagne_id')::bigint;IF support IS NULL THEN RETURN false;END IF;
 ELSIF p_table='photo_action_log' THEN
  IF p_action='read' AND actor_client IS NULL AND r IN ('Administrateur','Coordonnateur','Installateur') AND support IS NOT NULL
   AND NOT EXISTS(SELECT 1 FROM public.infrastructures i WHERE i.support_id=support)
   AND EXISTS(SELECT 1 FROM public.photo_action_log h WHERE h.id=(p_row->>'id')::bigint AND h.support_id=support)
  THEN RETURN true;END IF;
 ELSE RETURN false;END IF;
 IF phase IS NOT NULL THEN
  SELECT p.edt_id,p.client_id INTO phase_edt,phase_client FROM public.edt_phases p WHERE p.id=phase;
  IF NOT FOUND OR phase_edt IS NULL OR (edt IS NOT NULL AND edt<>phase_edt) OR (owner_client IS NOT NULL AND phase_client IS NOT NULL AND owner_client<>phase_client) THEN RETURN false;END IF;
  edt:=phase_edt;owner_client:=coalesce(owner_client,phase_client);
 END IF;
 IF public.tos_table_resource_scope(owner_client,support,campaign,edt,p_table='photo_action_log') IS NOT TRUE THEN RETURN false;END IF;
 IF r IN ('Client','Client-Admin') THEN
  IF edt IS NOT NULL THEN SELECT e.campagne_id INTO campaign FROM public.suivi_des_edt e WHERE e.id=edt;END IF;
  IF campaign IS NOT NULL AND public.client_can_access_campaign_v120(campaign) IS NOT TRUE THEN RETURN false;END IF;
 END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.tos_remaining_tenant_scope(p_table text, p_row jsonb, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text:=public.tos_current_role();a bigint;c bigint;camp bigint;edt bigint;s text;linked_support text;v bigint;vc bigint;vca bigint;phase bigint;pe bigint;pc bigint;payload jsonb;
BEGIN
 IF auth.uid() IS NULL OR r IS NULL OR p_row IS NULL OR p_action IS NULL OR p_action NOT IN ('read','write') THEN RETURN false;END IF;
 SELECT u.client_id INTO a FROM public.utilisateurs u WHERE u.auth_user_id=auth.uid() AND lower(coalesce(u.statut,''))='actif';
 IF a IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients x WHERE x.id=a) THEN RETURN false;END IF;
 IF r IN ('Client','Client-Admin') AND a IS NULL THEN RETURN false;END IF;
 IF p_table='role_ui_permissions' THEN RETURN p_action='read' OR (r='Administrateur' AND a IS NULL);END IF;
 IF p_table IN ('automation_bindings','automation_definitions','admin_change_log','relation_execution_logs','relation_test_logs','c_i_avec_enjeux') THEN
  RETURN a IS NULL AND r IN ('Administrateur','Coordonnateur','Installateur');
 END IF;
 IF p_table='operations_history' THEN
  IF a IS NULL AND r IN ('Administrateur','Coordonnateur','Installateur') THEN RETURN true;END IF;
  IF jsonb_typeof(p_row->'new_data')='object' AND jsonb_typeof(p_row->'old_data')='object' AND nullif(p_row->'new_data'->>'client_id','') IS NOT NULL AND nullif(p_row->'old_data'->>'client_id','') IS NOT NULL AND p_row->'new_data'->>'client_id'<>p_row->'old_data'->>'client_id' THEN RETURN false;END IF;
  FOR payload IN SELECT value FROM jsonb_array_elements(jsonb_build_array(p_row->'old_data',p_row->'new_data')) LOOP
   IF jsonb_typeof(payload)='object' AND coalesce(nullif(payload->>'client_id',''),nullif(payload->>'support_id',''),nullif(payload->>'campagne_id',''),nullif(payload->>'campaign_id',''),nullif(payload->>'edt_id','')) IS NOT NULL
    AND public.tos_table_resource_scope(nullif(payload->>'client_id','')::bigint,nullif(payload->>'support_id',''),nullif(coalesce(payload->>'campagne_id',payload->>'campaign_id'),'')::bigint,nullif(payload->>'edt_id','')::bigint,false) IS NOT TRUE THEN RETURN false;END IF;
  END LOOP;
  payload:=(CASE WHEN jsonb_typeof(p_row->'old_data')='object' THEN p_row->'old_data' ELSE '{}'::jsonb END)||(CASE WHEN jsonb_typeof(p_row->'new_data')='object' THEN p_row->'new_data' ELSE '{}'::jsonb END);
  RETURN public.tos_table_resource_scope(nullif(payload->>'client_id','')::bigint,nullif(payload->>'support_id',''),nullif(coalesce(payload->>'campagne_id',payload->>'campaign_id'),'')::bigint,nullif(payload->>'edt_id','')::bigint,false) IS TRUE;
 END IF;
 IF p_table NOT IN ('campagnes_maitres','campagnes_supports','edt_phase_reports','communications_finales','automation_resource_states','campagne_visuels_formats','reports','activity_events','edt_reports','requetes_clients','support_photos','photo_review_audit','email_outbox','email_delivery_log','terrain_sync_diagnostics','terrain_operations','client_campaign_access','client_member_invitations','campagnes_visuels_sites_supports','communications_operationnelles_sites_supports','client_request_supports') THEN RETURN false;END IF;
 -- Existing global internal reads include historical rows with legacy/unresolved references.
 IF p_action='read' AND a IS NULL AND r IN ('Administrateur','Coordonnateur','Installateur') THEN RETURN true;END IF;
 c:=nullif(p_row->>'client_id','')::bigint;s:=nullif(p_row->>'support_id','');
 camp:=nullif(coalesce(p_row->>'campagne_id',p_row->>'campaign_id'),'')::bigint;
 edt:=nullif(p_row->>'edt_id','')::bigint;
 IF nullif(p_row->>'target_client_id','') IS NOT NULL THEN
  IF c IS NOT NULL AND c<>(p_row->>'target_client_id')::bigint THEN RETURN false;END IF;
  IF public.tos_table_resource_scope((p_row->>'target_client_id')::bigint,nullif(p_row->>'target_support_id',''),null,null,false) IS NOT TRUE THEN RETURN false;END IF;
 END IF;
 IF nullif(p_row->>'infrastructure_id','') IS NOT NULL THEN
  SELECT i.client_id,i.support_id INTO vc,linked_support FROM public.infrastructures i WHERE i.id=(p_row->>'infrastructure_id')::bigint;
  IF NOT FOUND OR (c IS NOT NULL AND vc IS NOT NULL AND c<>vc) OR (s IS NOT NULL AND s<>linked_support) THEN RETURN false;END IF;
  c:=coalesce(c,vc);s:=coalesce(s,linked_support);
 END IF;
 IF p_table='client_campaign_access' THEN
  IF c IS NULL OR NOT EXISTS(SELECT 1 FROM public.utilisateurs u WHERE u.auth_user_id=(p_row->>'user_id')::uuid AND u.client_id=c AND lower(coalesce(u.statut,''))='actif' AND u.role IN ('Client','Client-Admin')) THEN RETURN false;END IF;
 END IF;
 IF p_table='campagnes_maitres' THEN camp:=NULL;IF c IS NULL THEN RETURN false;END IF;END IF;
 IF p_table='client_request_supports' THEN
  SELECT q.client_id INTO c FROM public.requetes_clients q WHERE q.id=(p_row->>'request_id')::bigint;
  IF NOT FOUND OR c IS NULL THEN RETURN false;END IF;
 END IF;
 IF p_table='photo_review_audit' THEN
  SELECT p.client_id,p.support_id,p.campagne_id INTO vc,s,camp FROM public.support_photos p WHERE p.id=(p_row->>'photo_id')::bigint;
  IF NOT FOUND OR (c IS NOT NULL AND vc IS NOT NULL AND c<>vc) THEN RETURN false;END IF;c:=coalesce(c,vc);
 END IF;
 v:=nullif(coalesce(p_row->>'visual_id',p_row->>'visuel_id'),'')::bigint;
 IF v IS NOT NULL THEN
  SELECT f.client_id,f.campagne_id INTO vc,vca FROM public.campagne_visuels_formats f WHERE f.id=v;
  IF NOT FOUND OR (c IS NOT NULL AND vc IS NOT NULL AND c<>vc) OR (camp IS NOT NULL AND vca IS NOT NULL AND camp<>vca) THEN RETURN false;END IF;
  c:=coalesce(c,vc);camp:=coalesce(camp,vca);
 END IF;
 phase:=nullif(coalesce(p_row->>'phase_id',p_row->>'edt_phase_id'),'')::bigint;
 IF phase IS NOT NULL THEN
  SELECT p.edt_id,p.client_id INTO pe,pc FROM public.edt_phases p WHERE p.id=phase;
  IF NOT FOUND OR pe IS NULL OR (edt IS NOT NULL AND edt<>pe) OR (c IS NOT NULL AND pc IS NOT NULL AND c<>pc) THEN RETURN false;END IF;
  edt:=pe;c:=coalesce(c,pc);
 END IF;
 RETURN public.tos_table_resource_scope(c,s,camp,edt,p_table IN ('automation_resource_states','activity_events','support_photos','photo_review_audit','terrain_operations')) IS TRUE;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.tos_storage_tenant_scope(p_bucket text, p_path text, p_action text, p_owner text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text:=public.tos_current_role();a bigint;s text;owner_client bigint;e bigint;p record;matched boolean:=false;
BEGIN
 IF p_bucket='terrain-photos' AND p_action='read' THEN RETURN true;END IF;
 IF auth.uid() IS NULL OR r IS NULL OR p_action IS NULL OR p_action NOT IN ('read','insert','update','delete') OR p_path IS NULL OR p_path='' OR p_path ~ '(^|/)[.][.]?(/|$)|//|[?#%]' THEN RETURN false;END IF;
 SELECT u.client_id INTO a FROM public.utilisateurs u WHERE u.auth_user_id=auth.uid() AND lower(coalesce(u.statut,''))='actif';
 IF a IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients c WHERE c.id=a) THEN RETURN false;END IF;
 IF r IN ('Client','Client-Admin') AND a IS NULL THEN RETURN false;END IF;
 IF p_action<>'read' AND r NOT IN ('Administrateur','Coordonnateur','Installateur') THEN RETURN false;END IF;
 IF p_action='insert' AND p_owner IS DISTINCT FROM auth.uid()::text THEN RETURN false;END IF;
 IF p_bucket='terrain-photos' THEN
  IF p_action='update' THEN RETURN false;END IF;
  s:=case when split_part(p_path,'/',1)='supports' then split_part(p_path,'/',2) else split_part(p_path,'/',1) end;
  RETURN public.tos_table_resource_scope(null,s,null,null,false) IS TRUE;
 ELSIF p_bucket='support-photos' THEN
  FOR p IN SELECT x.* FROM public.support_photos x WHERE coalesce(x.storage_bucket,'support-photos')='support-photos' AND (x.storage_path=p_path OR (x.assignment_pending AND x.target_storage_path=p_path)) LOOP
   matched:=true;
   IF public.tos_table_resource_scope(p.client_id,p.support_id,p.campagne_id,nullif(p.edt_id,'')::bigint,p.source='mass_import') IS NOT TRUE THEN RETURN false;END IF;
   IF p.assignment_pending AND public.tos_table_resource_scope(p.target_client_id,p.target_support_id,null,null,false) IS NOT TRUE THEN RETURN false;END IF;
   IF r IN ('Client','Client-Admin') AND ((p.client_visible IS NOT TRUE AND public.portal_view_allowed('Photos et inventaire') IS NOT TRUE) OR (public.client_can_access_campaign_v120(p.campagne_id) OR (p.deleted_at IS NULL AND public.portal_view_allowed('Photos et inventaire'))) IS NOT TRUE) THEN RETURN false;END IF;
  END LOOP;
  IF matched THEN RETURN true;END IF;
  IF r NOT IN ('Administrateur','Coordonnateur','Installateur') THEN RETURN false;END IF;
  s:=case when split_part(p_path,'/',1)='supports' then split_part(p_path,'/',2) else split_part(p_path,'/',1) end;
  IF public.tos_table_resource_scope(null,s,null,null,false) IS TRUE THEN RETURN true;END IF;
  RETURN a IS NULL AND (p_action='read' OR (r IN ('Administrateur','Coordonnateur') AND split_part(p_path,'/',1)='review'));
 ELSIF p_bucket='final-reports' THEN
  IF a IS NULL AND r IS DISTINCT FROM 'Administrateur' THEN RETURN false;END IF;
  IF r NOT IN ('Administrateur','Coordonnateur','Client','Client-Admin') THEN RETURN false;END IF;
  IF p_path !~* '[.]pdf$' OR (SELECT count(*) FROM public.suivi_des_edt x WHERE regexp_replace(coalesce(x.no_edt,x.id::text),'[^a-zA-Z0-9_-]','_','g')=split_part(p_path,'/',1))<>1 THEN RETURN false;END IF;
  SELECT x.id INTO e FROM public.suivi_des_edt x WHERE regexp_replace(coalesce(x.no_edt,x.id::text),'[^a-zA-Z0-9_-]','_','g')=split_part(p_path,'/',1);
  IF public.tos_table_resource_scope(null,null,null,e,false) IS NOT TRUE THEN RETURN false;END IF;
  IF EXISTS(SELECT 1 FROM public.edt_reports x WHERE x.report_path=p_path AND (x.edt_id IS DISTINCT FROM e OR x.storage_bucket IS DISTINCT FROM 'final-reports')) OR EXISTS(SELECT 1 FROM public.communications_finales x WHERE x.report_path=p_path AND x.edt_id IS DISTINCT FROM e::text) THEN RETURN false;END IF;
  FOR p IN SELECT x.edt_id,x.status,x.client_visible FROM public.edt_reports x WHERE x.report_path=p_path LOOP
   matched:=true;IF public.tos_table_resource_scope(null,null,null,p.edt_id,false) IS NOT TRUE THEN RETURN false;END IF;
   IF r IN ('Client','Client-Admin') AND (p.status IS DISTINCT FROM 'ready' OR p.client_visible IS NOT TRUE OR NOT EXISTS(SELECT 1 FROM public.suivi_des_edt x WHERE x.id=p.edt_id AND x.client_visible AND public.client_can_access_campaign_v120(x.campagne_id) IS TRUE)) THEN RETURN false;END IF;
  END LOOP;
  FOR p IN SELECT x.client_id,x.edt_id,x.client_published FROM public.communications_finales x WHERE x.report_path=p_path LOOP
   matched:=true;IF public.tos_table_resource_scope(p.client_id,null,null,nullif(p.edt_id,'')::bigint,false) IS NOT TRUE THEN RETURN false;END IF;
   IF r IN ('Client','Client-Admin') AND p.client_published IS NOT TRUE THEN RETURN false;END IF;
  END LOOP;
  IF matched THEN RETURN true;END IF;
  IF r NOT IN ('Administrateur','Coordonnateur') THEN RETURN false;END IF;
  IF (SELECT count(*) FROM public.suivi_des_edt x WHERE regexp_replace(coalesce(x.no_edt,x.id::text),'[^a-zA-Z0-9_-]','_','g')=split_part(p_path,'/',1))<>1 THEN RETURN false;END IF;
  SELECT x.id INTO e FROM public.suivi_des_edt x WHERE regexp_replace(coalesce(x.no_edt,x.id::text),'[^a-zA-Z0-9_-]','_','g')=split_part(p_path,'/',1);
  RETURN public.tos_table_resource_scope(null,null,null,e,false) IS TRUE;
 END IF;
 RETURN false;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.delete_or_archive_campaign_visual(p_visual_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  used_count bigint := 0;
BEGIN
IF (auth.uid() IS NOT NULL AND public.tos_current_role() IN ('Administrateur','Coordonnateur')) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_rpc_role_denied' USING ERRCODE='42501';END IF;
IF (NOT EXISTS(SELECT 1 FROM public.utilisateurs actor_profile WHERE actor_profile.auth_user_id=auth.uid() AND lower(coalesce(actor_profile.statut,''))='actif' AND actor_profile.client_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients actor_owner WHERE actor_owner.id=actor_profile.client_id))) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_actor_client_invalid' USING ERRCODE='42501';END IF;
IF (EXISTS(SELECT 1 FROM public.campagne_visuels_formats sec_visual WHERE sec_visual.id=p_visual_id AND public.tos_table_resource_scope(sec_visual.client_id,NULL,sec_visual.campagne_id,NULL,false))) IS NOT TRUE THEN RAISE EXCEPTION 'visual_scope_denied' USING ERRCODE='42501';END IF;

BEGIN

  if public.current_app_role() not in ('Administrateur','Coordonnateur') then
    raise exception 'Accès refusé.';
  end if;

  if to_regclass('public.support_photos') is not null then
    execute
      'select count(*) from public.support_photos where visuel_id = $1'
    into used_count
    using p_visual_id;
  end if;

  if used_count > 0 then
    update public.campagne_visuels_formats
    set
      actif = false,
      updated_at = now()
    where id = p_visual_id;

    return jsonb_build_object(
      'action', 'archived',
      'used_count', used_count
    );
  end if;

  delete from public.campagne_visuels_formats
  where id = p_visual_id;

  return jsonb_build_object(
    'action', 'deleted',
    'used_count', 0
  );
END;
END;
$function$

CREATE OR REPLACE FUNCTION public.diagnostic_systeme_v07()
 RETURNS TABLE(check_key text, title text, status text, actual_value text, expected_value text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
IF (auth.uid() IS NOT NULL AND public.tos_current_role() IN ('Administrateur','Coordonnateur','Installateur')) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_rpc_role_denied' USING ERRCODE='42501';END IF;
IF (NOT EXISTS(SELECT 1 FROM public.utilisateurs actor_profile WHERE actor_profile.auth_user_id=auth.uid() AND lower(coalesce(actor_profile.statut,''))='actif' AND actor_profile.client_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients actor_owner WHERE actor_owner.id=actor_profile.client_id))) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_actor_client_invalid' USING ERRCODE='42501';END IF;
IF (public.tos_table_resource_scope(NULL,NULL,NULL,NULL,true)) IS NOT TRUE THEN RAISE EXCEPTION 'global_internal_scope_required' USING ERRCODE='42501';END IF;
RETURN QUERY SELECT sec_result."check_key"::text,sec_result."title"::text,sec_result."status"::text,sec_result."actual_value"::text,sec_result."expected_value"::text,sec_result."detail"::text FROM (select'infrastructures','Infrastructures présentes',case when count(*)=6621 then'OK'else'Avertissement'end,count(*)::text,'6621',(6621-count(*))::text||' manquante(s)'from public.infrastructures union all select'arrets','Arrêts présents',case when count(*)>=4323 then'OK'else'Avertissement'end,count(*)::text,'4323','Total opérationnel'from public.liste_des_arrets union all select'visuels','Visuels configurés',case when count(*)>0 then'OK'else'Avertissement'end,count(*)::text,null,'Les visuels filtrent l’application terrain'from public.campagne_visuels_formats union all select'relations','Relations à confirmer',case when count(*)=0 then'OK'else'Avertissement'end,count(*)::text,'0','À confirmer dans le Studio'from public.relation_rules where validation_status<>'Validée' union all select'photos','Photos orphelines',case when count(*)=0 then'OK'else'Erreur'end,count(*)::text,'0','Support ID inexistant'from public.support_photos p where not exists(select 1 from public.infrastructures i where i.support_id=p.support_id)) AS sec_result("check_key","title","status","actual_value","expected_value","detail");
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_or_archive_master_campaign_v111(p_campaign_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.campagnes_maitres%rowtype; dependency_count bigint;
BEGIN
IF (auth.uid() IS NOT NULL AND public.tos_current_role() IN ('Administrateur','Coordonnateur')) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_rpc_role_denied' USING ERRCODE='42501';END IF;
IF (NOT EXISTS(SELECT 1 FROM public.utilisateurs actor_profile WHERE actor_profile.auth_user_id=auth.uid() AND lower(coalesce(actor_profile.statut,''))='actif' AND actor_profile.client_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients actor_owner WHERE actor_owner.id=actor_profile.client_id))) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_actor_client_invalid' USING ERRCODE='42501';END IF;
IF (EXISTS(SELECT 1 FROM public.campagnes_maitres sec_campaign WHERE sec_campaign.id=p_campaign_id AND public.tos_table_resource_scope(sec_campaign.client_id,NULL,NULL,NULL,false))) IS NOT TRUE THEN RAISE EXCEPTION 'campaign_scope_denied' USING ERRCODE='42501';END IF;

BEGIN

  if public.current_app_role() not in ('Administrateur','Coordonnateur') then raise exception 'Permission insuffisante.'; end if;
  select * into c from public.campagnes_maitres where id=p_campaign_id for update;
  if not found then raise exception 'Campagne introuvable.'; end if;
  select
    (select count(*) from public.campagne_visuels_formats where campagne_id=c.id)+
    (select count(*) from public.support_photos where campagne_id=c.id)+
    (select count(*) from public.suivi_des_edt where campagne_id=c.id)+
    (select count(*) from public.historique_des_campagnes where campagne=c.nom_campagne)
  into dependency_count;
  if dependency_count>0 then
    update public.campagnes_maitres set statut='Archivée',publiee_terrain=false,updated_at=now() where id=c.id;
    return jsonb_build_object('action','archived','dependencies',dependency_count);
  end if;
  delete from public.campagnes_maitres where id=c.id;
  return jsonb_build_object('action','deleted','dependencies',0);
END;
END;
$function$

CREATE OR REPLACE FUNCTION public.capture_activity_source_v113()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare j jsonb:=to_jsonb(new);v_time timestamptz;v_action text;v_module text;v_entity text;v_actor uuid;v_email text;v_confidence text:='exact';v_source_record text;
begin
  v_time=coalesce((j->>'created_at')::timestamptz,(j->>'changed_at')::timestamptz,(j->>'prise_le')::timestamptz,now());
  if tg_table_name='operations_history' then v_action=j->>'action';v_module='Opérations';v_entity=j->>'entity_type';v_actor=nullif(j->>'user_id','')::uuid;v_email=j->>'user_email';
  elsif tg_table_name='terrain_sync_diagnostics' then v_action=j->>'etape';v_module='Terrain';v_entity='terrain_sync';v_email=j->>'utilisateur';
  elsif tg_table_name='terrain_operations' then v_action=j->>'type_operation';v_module='Terrain';v_entity='terrain_operation';v_email=j->>'utilisateur';
  elsif tg_table_name='photo_action_log' then v_action=j->>'action';v_module='Photos';v_entity='photo';v_actor=nullif(j->>'user_id','')::uuid;
  elsif tg_table_name='journal_propagations' then v_action=j->>'declencheur';v_module='Campagnes';v_entity='propagation';v_email=j->>'utilisateur';
  elsif tg_table_name='relation_field_config_audit' then v_action='configuration_modifiee';v_module='Gestionnaire des champs';v_entity='relation_field';v_actor=nullif(j->>'changed_by','')::uuid;
  elsif tg_table_name='support_photos' then v_action='photo_ajoutee';v_module='Photos';v_entity='photo';v_email=j->>'utilisateur';v_confidence='derived';
  else return new; end if;
  if nullif(v_action,'') is null or nullif(j->>'id','') is null then return new; end if;
  v_source_record=j->>'id';
  if tg_table_name in('terrain_sync_diagnostics','terrain_operations') then v_source_record=concat_ws(':',v_source_record,coalesce(j->>'statut','unknown'),coalesce(j->>'etape','unknown'),coalesce(j->>'attempt','1')); end if;
  insert into public.activity_events(occurred_at,actor_id,actor_email,action,module,entity_type,entity_id,old_value,new_value,campaign_id,edt_id,support_id,client_id,source,status,metadata,source_system,source_record_id,source_occurred_at,reconstruction_method,confidence)
  values(v_time,v_actor,v_email,v_action,v_module,v_entity,coalesce(j->>'entity_id',j->>'entity_reference',j->>'reference',j->>'photo_id',j->>'relation_field_id',j->>'id'),j->'old_data',coalesce(j->'new_data',j),j->>'campagne_id',j->>'edt_id',j->>'support_id',j->>'client_id',tg_table_name,coalesce(j->>'statut',j->>'status',j->>'configuration_status'),j,tg_table_name,v_source_record,v_time,case when v_confidence='exact' then'direct'else'derived'end,v_confidence)
  on conflict(source_system,source_record_id) do nothing;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.client_ownership_summary_v1362(p_domain text DEFAULT NULL::text)
 RETURNS TABLE(client_id bigint, client_name text, domain text, total bigint, assigned bigint, without_client bigint, ambiguous bigint, other_client bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN
IF (auth.uid() IS NOT NULL AND public.tos_current_role() IN ('Administrateur')) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_rpc_role_denied' USING ERRCODE='42501';END IF;
IF (NOT EXISTS(SELECT 1 FROM public.utilisateurs actor_profile WHERE actor_profile.auth_user_id=auth.uid() AND lower(coalesce(actor_profile.statut,''))='actif' AND actor_profile.client_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients actor_owner WHERE actor_owner.id=actor_profile.client_id))) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_actor_client_invalid' USING ERRCODE='42501';END IF;

BEGIN
 if auth.uid()is null or not exists(select 1 from public.utilisateurs where auth_user_id=auth.uid()and statut='Actif'and role='Administrateur')then raise exception 'ADMIN_REQUIRED' using errcode='42501';end if;return query with d as(select i.client_id,'infrastructures'::text domain,count(*)::bigint total from public.infrastructures i group by i.client_id union all select c.client_id,'campaigns',count(*)from public.campagnes_maitres c group by c.client_id union all select p.client_id,'photos',count(*)from public.support_photos p group by p.client_id union all select e.client_id,'edt',count(*)from public.suivi_des_edt e group by e.client_id union all select p.client_id,'edt_phases',count(*)from public.edt_phases p group by p.client_id union all select e.client_id,'issues',count(*)from public.enjeux_terrain e group by e.client_id union all select r.client_id,'requests',count(*)from public.requetes_clients r group by r.client_id union all select v.client_id,'visuals',count(*)from public.campagne_visuels_formats v group by v.client_id union all select b.client_id,'work_orders',count(*)from public.bons_de_travail b group by b.client_id)select d.client_id,c.nom_client,d.domain,d.total,case when d.client_id is null then 0 else d.total end,case when d.client_id is null then d.total else 0 end,0::bigint,0::bigint from d left join public.clients c on c.id=d.client_id where (p_domain is null or d.domain=p_domain) AND public.tos_table_resource_scope(d.client_id,NULL,NULL,NULL,true);END;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_transfer_data_client_v1362(p_domain text, p_entity_id text, p_new_client_id bigint, p_confirmation boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v_actor uuid:=auth.uid();v_old bigint;v_changed integer;BEGIN
IF (auth.uid() IS NOT NULL AND public.tos_current_role() IN ('Administrateur')) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_rpc_role_denied' USING ERRCODE='42501';END IF;
IF (NOT EXISTS(SELECT 1 FROM public.utilisateurs actor_profile WHERE actor_profile.auth_user_id=auth.uid() AND lower(coalesce(actor_profile.statut,''))='actif' AND actor_profile.client_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients actor_owner WHERE actor_owner.id=actor_profile.client_id))) IS NOT TRUE THEN RAISE EXCEPTION 'canonical_actor_client_invalid' USING ERRCODE='42501';END IF;
IF (public.tos_table_resource_scope(NULL,NULL,NULL,NULL,true)) IS NOT TRUE THEN RAISE EXCEPTION 'global_internal_scope_required' USING ERRCODE='42501';END IF;

BEGIN
 if v_actor is null or not exists(select 1 from public.utilisateurs where auth_user_id=v_actor and statut='Actif'and role='Administrateur')then raise exception 'ADMIN_REQUIRED' using errcode='42501';end if;if not coalesce(p_confirmation,false)then raise exception 'TRANSFER_CONFIRMATION_REQUIRED';end if;if not exists(select 1 from public.clients where id=p_new_client_id and statut='Actif')then raise exception 'TARGET_CLIENT_NOT_FOUND';end if;if p_domain='infrastructures'then select client_id into v_old from public.infrastructures where support_id=p_entity_id for update;update public.infrastructures set client_id=p_new_client_id where support_id=p_entity_id;get diagnostics v_changed=row_count;elsif p_domain='campaigns'then select client_id into v_old from public.campagnes_maitres where id=p_entity_id::bigint for update;update public.campagnes_maitres set client_id=p_new_client_id where id=p_entity_id::bigint;get diagnostics v_changed=row_count;update public.campagnes_supports set client_id=p_new_client_id where campagne_id=p_entity_id::bigint;update public.campagne_visuels_formats set client_id=p_new_client_id where campagne_id=p_entity_id::bigint;update public.support_photos set client_id=p_new_client_id where campagne_id=p_entity_id::bigint;update public.suivi_des_edt set client_id=p_new_client_id where campagne_id=p_entity_id::bigint;delete from public.client_campaign_access where campaign_id=p_entity_id::bigint;else raise exception 'UNSUPPORTED_TRANSFER_DOMAIN';end if;if v_changed<>1 then raise exception 'TRANSFER_ENTITY_NOT_FOUND';end if;insert into public.activity_events(occurred_at,actor_id,action,module,entity_type,entity_id,old_value,new_value,client_id,source,source_system,source_record_id,source_occurred_at,reconstruction_method,confidence,status)values(now(),v_actor,'DATA_TRANSFERRED_CLIENT','client_ownership',p_domain,p_entity_id,jsonb_build_object('client_id',v_old),jsonb_build_object('client_id',p_new_client_id),p_new_client_id::text,'admin','admin',p_entity_id,now(),'direct','exact','success');return jsonb_build_object('ok',true,'domain',p_domain,'entity_id',p_entity_id,'old_client_id',v_old,'new_client_id',p_new_client_id);END;
END;
$function$

CREATE OR REPLACE FUNCTION public.appliquer_campagne_support(p_support_id text, p_campagne_id bigint, p_utilisateur text DEFAULT NULL::text, p_photo_url text DEFAULT NULL::text, p_photo_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.campagnes_maitres%rowtype;
declare op uuid:=gen_random_uuid();
declare v_role text;
declare v_actor_client bigint;
declare v_client bigint;
begin

  if auth.uid() is null then
    raise exception 'unauthorized' using errcode='42501';
  end if;
  begin
    select u.role, u.client_id into strict v_role, v_actor_client
    from public.utilisateurs u
    where u.auth_user_id=auth.uid() and lower(coalesce(u.statut,''))='actif'
    for share;
  exception when no_data_found or too_many_rows then
    raise exception 'unauthorized' using errcode='42501';
  end;
  if v_role is null or v_role not in ('Administrateur','Coordonnateur','Installateur') then
    raise exception 'forbidden' using errcode='42501';
  end if;
  -- Internal staff may have global scope (explicitly approved).
  -- A populated profile client always restricts that scope.
  select * into c from public.campagnes_maitres where id=p_campagne_id and publiee_terrain=true for update;
  if not found then raise exception 'Campagne non publiée ou introuvable.'; end if;

  select client_id into v_client from public.infrastructures where support_id=p_support_id for update;
  if not found then raise exception 'resource_not_found' using errcode='P0002'; end if;

  if v_client is null or not exists(select 1 from public.clients where id=v_client)
     or (v_actor_client is not null and v_actor_client is distinct from v_client) then
    raise exception 'client_scope_denied' using errcode='42501';
  end if;

  if c.client_id is null or c.client_id is distinct from v_client then
    raise exception 'cross_client_denied' using errcode='42501';
  end if;
  perform 1 from public.campagnes_supports where campagne_id=c.id and support_id=p_support_id for update;
  if exists(select 1 from public.campagnes_supports where campagne_id=c.id and support_id=p_support_id
            and client_id is distinct from v_client) then
    raise exception 'cross_client_denied' using errcode='42501';
  end if;

  update public.infrastructures set
    campagne_actuelle=c.nom_campagne,
    campagne_selon_visuel=c.nom_campagne,
    visuel_campagne=c.visuel_generique,
    visuel_en_expo=coalesce(c.visuel_generique,visuel_en_expo),
    edt_associe=coalesce(c.no_edt,edt_associe),
    date_derniere_manipulation=now()::text,
    updated_at=now()
  where support_id=p_support_id;

  insert into public.campagnes_supports(campagne_id,support_id,statut,visuel_attendu,no_edt,photo_url,date_completion,utilisateur_completion,updated_at)
  values(c.id,p_support_id,'Terminée',c.visuel_generique,c.no_edt,p_photo_url,now(),p_utilisateur,now())
  on conflict(campagne_id,support_id) do update set statut='Terminée',visuel_attendu=excluded.visuel_attendu,no_edt=excluded.no_edt,photo_url=coalesce(excluded.photo_url,campagnes_supports.photo_url),date_completion=now(),utilisateur_completion=excluded.utilisateur_completion,updated_at=now();

  insert into public.historique_des_campagnes(support_id,campagne,visuel,no_edt,date_installation,photo_installation,utilisateur,raw_data)
  values(p_support_id,c.nom_campagne,c.visuel_generique,c.no_edt,now()::text,p_photo_url,p_utilisateur,jsonb_build_object('operation_id',op,'photo_path',p_photo_path));

  insert into public.journal_propagations(operation_id,campagne_id,support_id,declencheur,statut,details,utilisateur)
  values(op,c.id,p_support_id,'Campagne sélectionnée dans application terrain','Réussi',jsonb_build_object('infrastructure',true,'historique',true,'photo_url',p_photo_url),p_utilisateur);

  return jsonb_build_object('operation_id',op,'support_id',p_support_id,'campagne',c.nom_campagne,'visuel',c.visuel_generique,'no_edt',c.no_edt,'statut','Réussi');
end;
$function$
